         split; [ rewrite app_length, skipn_length; apply Nat2Z.inj; rewrite Nat2Z.inj_add, HlX, LXlo; xlia Han LX |];
         split; [ rewrite skipn_app, skipn_all2 by (apply Nat2Z.inj_le; rewrite HlX, LXlo; xlia Han);
                  replace (Z.to_nat an - length lX)%nat with 0%nat by (apply Nat2Z.inj; rewrite Nat2Z.inj_sub, HlX, LXlo by (apply Nat2Z.inj_le; rewrite HlX, LXlo; xlia Han); xlia Han); reflexivity |];
         split; [ apply u32arr_app; split; [exact HuT|]; rewrite HlT, LTlo; eapply u32arr_transport; [exact (unlock _ HThi') | exact MU' | exact Hw |];
                  cbn [disjoint_from]; rewrite skipn_length; klia |];
         split; [ rewrite app_length, skipn_length; apply Nat2Z.inj; rewrite Nat2Z.inj_add, HlT, LTlo; xlia Han LT |];
         split; [ rewrite skipn_app, skipn_all2 by (apply Nat2Z.inj_le; rewrite HlT, LTlo; xlia Han);
                  replace (Z.to_nat (2 * an + 1) - length lT)%nat with 0%nat by (apply Nat2Z.inj; rewrite Nat2Z.inj_sub, HlT, LTlo by (apply Nat2Z.inj_le; rewrite HlT, LTlo; xlia Han); xlia Han); reflexivity |];
         exact Hs
       end end end end end end end end.
  all: match goal with |- ?g => idtac "LEFT" g end.
Qed.
